<?php
// logout.php
// ==========================
// صفحة تسجيل الخروج النهائية
// ==========================

session_start();

/*
 |----------------------------------
 | 1) تفريغ جميع متغيرات الجلسة
 |----------------------------------
*/
$_SESSION = [];

/*
 |----------------------------------
 | 2) حذف كوكي الجلسة (إن وجد)
 |----------------------------------
*/
if (ini_get("session.use_cookies")) {
    $params = session_get_cookie_params();
    setcookie(
        session_name(),
        '',
        time() - 42000,
        $params['path'],
        $params['domain'],
        $params['secure'],
        $params['httponly']
    );
}

/*
 |----------------------------------
 | 3) تدمير الجلسة نهائيًا
 |----------------------------------
*/
session_destroy();

/*
 |----------------------------------
 | 4) إعادة التوجيه إلى صفحة الدخول
 |----------------------------------
*/
header("Location: login.php?logout=1");
exit;
